-- D1 / SQLite: new empty rehearsal database only. IDs are generated by Worker.
-- updated_at and event_state insertion are managed by Worker commands.
-- No RLS / GRANT / Postgres functions. Authorization must be enforced in Worker.

create table sponsors (
  id          TEXT PRIMARY KEY NOT NULL,
  name        TEXT not null,
  shop_name   TEXT,
  contact     TEXT,
  note        TEXT,
  is_active   INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at  TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create table media_assets (
  id            TEXT PRIMARY KEY NOT NULL,
  title         TEXT not null,
  kind          TEXT not null
                check (kind in ('video', 'image', 'audio')),

  source        TEXT not null
                check (source in ('storage', 'external')),
  storage_path  TEXT,
  external_url  TEXT,
  mime_type     TEXT,
  duration_sec  REAL,
  width         INTEGER,
  height        INTEGER,

  has_alpha     INTEGER NOT NULL DEFAULT 0 CHECK (has_alpha IN (0, 1)),

  preload       INTEGER NOT NULL DEFAULT 0 CHECK (preload IN (0, 1)),
  sponsor_id    TEXT references sponsors(id) on delete set null,
  note          TEXT,
  created_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),

  constraint media_assets_source_chk check (
    (source = 'storage'  and storage_path is not null) or
    (source = 'external' and external_url is not null)
  )
);

create index idx_media_assets_sponsor on media_assets(sponsor_id);

create index idx_media_assets_preload on media_assets(preload) where preload = 1;

create table events (
  id            TEXT PRIMARY KEY NOT NULL,

  title         TEXT not null,
  subtitle      TEXT,
  venue         TEXT,

  format        TEXT not null default 'double_elimination'
                check (format in ('double_elimination', 'single_elimination', 'round_robin')),

  team_size     INTEGER not null default 2 check (team_size between 1 and 6),

  draw_mode     TEXT not null default 'full_random'
                check (draw_mode in ('full_random', 'rating_balanced', 'manual')),

  status        TEXT not null default 'draft'
                check (status in ('draft', 'entry', 'drawn', 'running', 'finished', 'archived')),

  scoring_mode  TEXT not null default 'win_loss'
                check (scoring_mode in ('win_loss', 'legs')),
  show_scores   INTEGER NOT NULL DEFAULT 0 CHECK (show_scores IN (0, 1)),

  theme         TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(theme)),

  settings      TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings)),

  bracket_snapshot TEXT CHECK (bracket_snapshot IS NULL OR json_valid(bracket_snapshot)),
  odd_strategy TEXT NOT NULL DEFAULT 'trio' CHECK (odd_strategy IN ('trio','bye')),
  bm_current_match_id INTEGER,
  environment TEXT NOT NULL DEFAULT 'rehearsal' CHECK (environment IN ('rehearsal','live')),
  starts_at     TEXT,
  created_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_events_status on events(status);

create table participants (
  id              TEXT PRIMARY KEY NOT NULL,
  event_id        TEXT not null references events(id) on delete cascade,
  entry_no        INTEGER,
  display_name    TEXT not null,
  name_kana       TEXT,

  rating          REAL,
  home_shop       TEXT,
  photo_media_id  TEXT references media_assets(id) on delete set null,
  photo_url       TEXT,
  photo_path TEXT,
  face_crop_path TEXT,
  status          TEXT not null default 'entered'
                  check (status in ('entered', 'withdrawn', 'reserve')),
  note            TEXT,
  created_at      TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),

  constraint participants_entry_no_uniq unique (event_id, entry_no)
);

create index idx_participants_event on participants(event_id);

create table draw_sessions (
  id            TEXT PRIMARY KEY NOT NULL,
  event_id      TEXT not null references events(id) on delete cascade,
  mode          TEXT not null
                check (mode in ('full_random', 'rating_balanced', 'manual')),

  seed          TEXT,

  reveal_order  TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(reveal_order)),

  committed_at  TEXT,
  created_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_draw_sessions_event on draw_sessions(event_id);

create table teams (
  id               TEXT PRIMARY KEY NOT NULL,
  event_id         TEXT not null references events(id) on delete cascade,
  draw_session_id  TEXT references draw_sessions(id) on delete set null,
  manager_participant_id INTEGER,
  name             TEXT,
  seed             INTEGER,
  rating_total     REAL,
  created_at       TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_teams_event on teams(event_id);

create index idx_teams_draw_session on teams(draw_session_id);

create table team_members (
  team_id         TEXT not null references teams(id) on delete cascade,
  participant_id  TEXT not null references participants(id) on delete cascade,
  position        INTEGER not null default 1,
  primary key (team_id, participant_id)
);

create index idx_team_members_participant on team_members(participant_id);

create table matches (
  id                  TEXT PRIMARY KEY NOT NULL,
  event_id            TEXT not null references events(id) on delete cascade,

  bracket             TEXT not null
                      check (bracket in ('winners', 'losers', 'grand_final')),
  round               INTEGER not null,
  match_no            INTEGER not null,

  sequence            INTEGER,

  team_a_id           TEXT references teams(id) on delete set null,
  team_b_id           TEXT references teams(id) on delete set null,
  winner_team_id      TEXT references teams(id) on delete set null,
  loser_team_id       TEXT references teams(id) on delete set null,

  score_a             INTEGER,
  score_b             INTEGER,

  status              TEXT not null default 'pending'
                      check (status in ('pending', 'ready', 'in_progress', 'done', 'void')),

  next_win_match_id   TEXT references matches(id) on delete set null,
  next_win_slot       INTEGER check (next_win_slot in (1, 2)),
  next_lose_match_id  TEXT references matches(id) on delete set null,
  next_lose_slot      INTEGER check (next_lose_slot in (1, 2)),

  layout              TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(layout)),

  started_at          TEXT,
  finished_at         TEXT,
  created_at          TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),

  constraint matches_position_uniq unique (event_id, bracket, round, match_no)
);

create index idx_matches_event_sequence on matches(event_id, sequence);

create index idx_matches_event_bracket  on matches(event_id, bracket, round);

create index idx_matches_team_a on matches(team_a_id);

create index idx_matches_team_b on matches(team_b_id);

create table event_state (
  event_id          TEXT primary key references events(id) on delete cascade,

  scene             TEXT not null default 'idle'
                    check (scene in (
                      'idle', 'opening', 'draw', 'bracket',
                      'vs_card', 'match_live', 'result',
                      'interval', 'award', 'finished'
                    )),
  scene_payload     TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(scene_payload)),

  version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
  playback TEXT NOT NULL DEFAULT 'holding' CHECK (playback IN ('playing','paused','holding','error')),
  playback_position_ms INTEGER NOT NULL DEFAULT 0 CHECK (playback_position_ms >= 0),
  scene_seq         INTEGER not null default 0,
  scene_started_at  TEXT,

  awaiting_operator INTEGER NOT NULL DEFAULT 0 CHECK (awaiting_operator IN (0, 1)),

  current_match_id  TEXT references matches(id) on delete set null,

  presentation_mode TEXT not null default 'full'
                    check (presentation_mode in ('full', 'short', 'lite')),
  audio_enabled     INTEGER NOT NULL DEFAULT 1 CHECK (audio_enabled IN (0, 1)),

  updated_at        TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create table operation_log (
  id            INTEGER PRIMARY KEY,
  event_id      TEXT not null references events(id) on delete cascade,
  actor_id TEXT,
  request_id TEXT,
  version INTEGER,
  action        TEXT not null,
  target_table  TEXT,
  target_id     TEXT,
  before_data   TEXT,
  after_data    TEXT,
  undone_at     TEXT,
  created_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_operation_log_undo
  on operation_log(event_id, id desc)
  where undone_at is null;

create table playlists (
  id          TEXT PRIMARY KEY NOT NULL,

  event_id    TEXT references events(id) on delete cascade,
  slot        TEXT not null
              check (slot in ('opening', 'interval', 'standby', 'award')),
  name        TEXT not null,
  is_loop     INTEGER NOT NULL DEFAULT 1 CHECK (is_loop IN (0, 1)),

  is_locked   INTEGER NOT NULL DEFAULT 0 CHECK (is_locked IN (0, 1)),
  created_at  TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_playlists_event_slot on playlists(event_id, slot);

create table playlist_items (
  id            TEXT PRIMARY KEY NOT NULL,
  playlist_id   TEXT not null references playlists(id) on delete cascade,
  media_id      TEXT not null references media_assets(id) on delete restrict,

  order_no      REAL not null default 0,

  duration_sec  REAL,
  is_locked     INTEGER NOT NULL DEFAULT 0 CHECK (is_locked IN (0, 1)),
  is_enabled    INTEGER NOT NULL DEFAULT 1 CHECK (is_enabled IN (0, 1)),
  created_at    TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index idx_playlist_items_order on playlist_items(playlist_id, order_no);

create index idx_playlist_items_media on playlist_items(media_id);

create table ad_impressions (
  id                INTEGER PRIMARY KEY,
  event_id          TEXT references events(id) on delete set null,
  playlist_item_id  TEXT references playlist_items(id) on delete set null,
  media_id          TEXT references media_assets(id) on delete set null,
  sponsor_id        TEXT references sponsors(id) on delete set null,
  shown_at          TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  duration_ms       INTEGER,
  is_completed      INTEGER NOT NULL DEFAULT 0 CHECK (is_completed IN (0, 1))
);

create index idx_ad_impressions_event   on ad_impressions(event_id, media_id);

create index idx_ad_impressions_sponsor on ad_impressions(sponsor_id, shown_at);

create table presentation_presets (
  id          TEXT PRIMARY KEY NOT NULL,
  name        TEXT not null,
  description TEXT,
  config      TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(config)),
  is_default  INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  created_at  TEXT not null DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
